"""Read-only run verification plus small retained assessment/inventory reports."""
import datetime,fcntl,gzip,hashlib,json,shutil,subprocess
from pathlib import Path
import psutil
H=Path(__file__).resolve().parent;ROOT=H.parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(name,x):(H/name).write_text(json.dumps(x,indent=2)+'\n')
p=H/'pressure-grid-frozen-plan-nov3.json';plan=json.loads(p.read_text());state=json.loads((H/'live-nov3-pressure-grid-custody.json').read_text());analysis=json.loads((H/'live-nov3-pressure-grid-independent-analysis.json').read_text())
bad=[n for n,v in plan['file_pins'].items() if not (ROOT/n).is_file() or sha(ROOT/n)!=v];assert not bad
assert sha(p)==state['manifest_sha256']
assert state['status']=='complete' and len(state['runs'])==8 and not state['owned_descendants_remaining']
assert all(q['exit_code']==0 and q['workflow_success'] and not q['owned_descendants_remaining'] for q in state['runs'])
assert not psutil.pid_exists(state['supervisor_pid'])
assert all(not psutil.pid_exists(q['runner_pid']) for q in state['runs'])
gpu=subprocess.check_output(['nvidia-smi','--query-compute-apps=pid,process_name','--format=csv,noheader'],text=True).strip();assert not gpu
with open('/tmp/vllm-semantic-cache-gpu.lock','a') as f:fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB);fcntl.flock(f,fcntl.LOCK_UN)
selection=[];raw_checks=[];files=[]
for n,r in analysis['rows'].items():
 rawpath=ROOT/r['raw'];raw=json.load(gzip.open(rawpath,'rt'));assert sha(rawpath)==r['raw_sha256']
 assert all(q['payload']['max_tokens']==raw['geometry']['max_model_len']-len(q['payload']['prompt']) for q in raw['requests'])
 for group,group_pins in r['pins'].items():
  if group not in ['source_pins','runtime_pins','pins','harness_pins','artifact_pins']:continue
  for key,value in group_pins.items():
   root=ROOT/raw['args']['source_dir'] if group=='source_pins' else ROOT if group=='harness_pins' else H
   full=root/key;assert sha(full)==value,(n,group,key)
 q=max(raw['requests'],key=lambda q:len(q.get('output_token_ids',[])))
 selection.append({'run':n,'request_index':q['index'],'tokens':len(q['output_token_ids']),'text_sha256':hashlib.sha256(q['generated_text'].encode()).hexdigest(),'finding':'No conspicuous looping. Ladder response contains invalid physics/algebra/arithmetic; answer-quality defects occur in both arms. Not a cache-corruption attribution.'})
 counts=r['scheduler_counts'];assert counts['store_accepted_keys']==counts['store_completed_keys']
 raw_checks.append({'run':n,'pins_match':True,'remaining_context_only':True,'accepted_completed_stores_balance':True,'explicit_store_failed_keys':counts.get('store_failed_keys'),'missing_failure_counter_meaning':'Unavailable explicitly; do not interpret absent counter alone as zero.','raw_sha256':sha(rawpath)})
 files.extend(f for f in rawpath.parent.rglob('*') if f.is_file())
files.extend(H/q['console']['path'].split('/')[-1] for q in state['runs'])
files=list(dict.fromkeys(files));inventory=[{'path':str(f.relative_to(ROOT)),'bytes':f.stat().st_size} for f in files]
summary={'schema':'astra-pressure-grid-assessment-v1','scope':'Four paired discovery workflows on spent seed3301, one observation per arm per geometry; no confidence intervals or production qualification.','outcome':'No geometry merits confirmation over the existing GPU1024/CPU1024/active8 candidate. Overall production objective remains unfulfilled.','completed_invocations':8,'natural_eos':576,'failed_requests':0,'comparisons':analysis['comparisons'],'findings':['GPU768/CPU1024 preserves lower first-prefill local attribution (14409 native versus 10927 candidate) and more H2D, but only +1.25% workflow and +0.69% token rate; TTFT slightly worse.','GPU1024/CPU512 and CPU256 have zero H2D in both arms. CPU eviction pressure destroys usable chains rather than enabling a retention advantage. CPU256 also has approximately770 refused store preparation calls per run.','GPU512/CPU1024/active4 has 9 candidate versus3 native preemptions; candidate transfers1.47GB H2D versus1.02GB native and has worse workflow/TTFT. Initial-prefill attribution must not be treated as total executed work when preemptions occur.','Matched-arm startup/serving NVML and CUDA allocated/reserved peaks are identical within each pair. GPU capacity reductions save serving memory generically, not uniquely through advice. Startup NVML remains7953.871MiB for every run.','Sampled server CPU differences range -0.79 to+0.72 seconds; sampled summed RSS differences range -226.01 to+227.82MiB, with shared-page double counting. No stable host resource advantage demonstrated.'],'raw_checks':raw_checks,'quality':{'heuristic_flags':sum(r['output_screen']['flagged'] for r in analysis['rows'].values()),'manually_inspected':'Longest response in each of8 runs,4 unique texts; targeted limited review, not quality equivalence.','selection':selection},'next_recommendation':'Stop this chat geometry grid. Screen a meaningful repository-triage profile with long recorded observations and naturally short status answers, symmetrically applied, actual generated history and natural EOS; retain all failures. Begin matchedGPU1024/CPU1024/active8. Fixed historical observations are not executed task success. No additional runs authorized to this agent in this block.'}
save('live-nov3-pressure-grid-independent-assessment.json',summary)
service={'schema':'astra-service-wrapper-readonly-review-v1','pins':{n:sha(H/n) for n in ['run_live_service_nov3.py','live_service_workload_nov3.py']},'assessment':'Suitable for separate service-profile discovery after straightforward preflight hardening. No GPU run or wrapper edit performed.','verified':['System profile is arm-independent.','Default concise_support_v1 text equals prior support prompt.','Standard messages_for_turn uses actual generated responses; recorded historical assistant replies are not substituted.','Request max_tokens is remaining context only; no forced replay/output cap added.','Actual service driver/workload are archived and pinned under correct names.','Hint producer retains constant750ms estimate and pending flag, no future observation/private deadline input.','Workload explicitly records recorded_tools_executed=False.'],'issues':[{'severity':'configuration footgun','finding':'--service-profile repository_triage_v1 has no effect without --support-profile; require or autoactivate explicit profile selection before freezing.'},{'severity':'path robustness','finding':'Artifact pin generation calls corpus_path.relative_to(H); an external corpus path raises ValueError before raw failure recording. H-local paths currently work; support arbitrary paths or validate the restriction.'},{'severity':'provenance contract','finding':'New corpus tokenizer field controls actual tokenizer loading while corpus_identity reports model selection revision. Validate tokenizer identity/schema against pinned model selection for custom corpora, and retain the corpus under immutable manifest pins.'}],'limitations':['Repository triage profile plausibly targets naturally short outputs with reusable evidence, but performance and answer adequacy remain unmeasured.','Original public issue prompt can request patches while the system asks status only; the evaluated application contract must explicitly be status triage, not issue resolution.','Prepared source text was token-budget truncated previously; report that normalization and recorded-observation limitations.','New corpus should be pinned before invocation and at end; per-run hashing alone is not a full mutation guard.']}
save('live-nov3-service-wrapper-astra-review.json',service)
inv={'schema':'astra-pressure-grid-handback-v1','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'custody':'ASTRA -> ROOT','pins_checked':len(plan['file_pins']),'pin_mismatches':bad,'plan_matches_custody':True,'supervisor_exited':True,'all_runner_processes_exited':True,'all_raw_descendant_lists_empty':True,'gpu_compute_processes':gpu,'gpu_lock_available':True,'owned_processes_remaining':[],'artifact_bytes_retained':sum(x['bytes'] for x in inventory),'largest_retained':sorted(inventory,key=lambda x:x['bytes'],reverse=True)[:12],'retention_reason':'Compressed raw results/server/driver logs and archived sources are useful negative evidence. No disposable owned worktrees, downloads or checkpoints created. Shared model/kernel caches and prior results preserved.','deleted':[],'free_bytes_before_campaign':state['free_bytes_before'],'free_bytes_after_campaign':state['free_bytes_after'],'free_bytes_at_handback':shutil.disk_usage(H).free,'space_claim':'No deletion/reclamation claim; filesystem delta includes concurrent parent artifacts.'}
save('live-nov3-pressure-grid-handback-inventory.json',inv)
print(json.dumps({'pins_checked':inv['pins_checked'],'retained_bytes':inv['artifact_bytes_retained'],'gpu_free':True,'runs':8,'natural_eos':576,'assessment':summary['outcome']}))
